import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { Button } from '../components/ui/button';
import { FaHome, FaSearch, FaArrowLeft } from 'react-icons/fa';

const NotFoundPage = () => {
    const navigate = useNavigate();
    const { user } = useAuth();

    return (
        <div className="min-h-screen bg-gray-50 flex items-center justify-center px-4">
            <div className="max-w-lg w-full text-center">
                {/* 404 Illustration */}
                <div className="mb-8">
                    <h1 className="text-9xl font-bold text-gray-300 mb-4">404</h1>
                    <div className="w-32 h-1 bg-gradient-to-r from-blue-500 to-purple-500 mx-auto mb-6"></div>
                </div>

                {/* Error Message */}
                <h2 className="text-3xl font-bold text-gray-900 mb-4">
                    Page Not Found
                </h2>
                <p className="text-gray-600 mb-8 text-lg">
                    Sorry, the page you're looking for doesn't exist or has been moved.
                    Let's get you back on track!
                </p>

                {/* Error Details for Development */}
                {process.env.NODE_ENV === 'development' && (
                    <div className="bg-gray-100 rounded-lg p-4 mb-8 text-left">
                        <p className="text-sm text-gray-700 font-mono">
                            <strong>Debug Info:</strong> No route matched for this URL.
                            Check your routing configuration in App.js
                        </p>
                    </div>
                )}

                {/* Action Buttons */}
                <div className="space-y-4">
                    <div className="flex flex-col sm:flex-row gap-4 justify-center">
                        {/* Go Home Button */}
                        <Button
                            onClick={() => navigate('/homepage')}
                            className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-lg font-medium transition-colors flex items-center justify-center gap-2"
                        >
                            <FaHome className="w-4 h-4" />
                            Go Home
                        </Button>

                        {/* Go Back Button */}
                        <Button
                            onClick={() => navigate(-1)}
                            variant="outline"
                            className="border-gray-300 text-gray-700 hover:bg-gray-50 px-6 py-3 rounded-lg font-medium transition-colors flex items-center justify-center gap-2"
                        >
                            <FaArrowLeft className="w-4 h-4" />
                            Go Back
                        </Button>
                    </div>

                    {/* Browse Rooms Link */}
                    <div className="pt-4">
                        <Link 
                            to="/rooms"
                            className="text-blue-600 hover:text-blue-700 font-medium inline-flex items-center gap-2 transition-colors"
                        >
                            <FaSearch className="w-4 h-4" />
                            Browse Available Rooms
                        </Link>
                    </div>
                </div>

                {/* Additional Help Section */}
                <div className="mt-12 p-6 bg-white rounded-lg shadow-sm">
                    <h3 className="text-lg font-semibold text-gray-900 mb-3">
                        Looking for something specific?
                    </h3>
                    <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 text-sm">
                        <div>
                            <Link 
                                to="/rooms"
                                className="text-blue-600 hover:text-blue-700 font-medium block"
                            >
                                Find Rooms
                            </Link>
                            <p className="text-gray-500 mt-1">Browse available accommodation</p>
                        </div>
                        <div>
                            <Link 
                                to="/mess"
                                className="text-blue-600 hover:text-blue-700 font-medium block"
                            >
                                Find Mess Services
                            </Link>
                            <p className="text-gray-500 mt-1">Discover meal plans</p>
                        </div>
                        <div>
                            {user ? (
                                <Link 
                                    to="/dashboard"
                                    className="text-blue-600 hover:text-blue-700 font-medium block"
                                >
                                    My Dashboard
                                </Link>
                            ) : (
                                <Link 
                                    to="/login"
                                    className="text-blue-600 hover:text-blue-700 font-medium block"
                                >
                                    Sign In
                                </Link>
                            )}
                            <p className="text-gray-500 mt-1">
                                {user ? 'Manage your bookings' : 'Access your account'}
                            </p>
                        </div>
                    </div>
                </div>

                {/* Report Issue Link */}
                <div className="mt-8 text-sm">
                    <p className="text-gray-500">
                        If you believe this is an error, please{' '}
                        <a 
                            href="mailto:support@dormanddish.com" 
                            className="text-blue-600 hover:text-blue-700 font-medium"
                        >
                            report the issue
                        </a>
                    </p>
                </div>
            </div>
        </div>
    );
};

export default NotFoundPage;